const shards = [s0, s1, s2, s3];   // physical shards, count may grow

function shardFor(userId) {
  return shards[hash(userId) % shards.length];   // route by user
}

function getUser(userId) {
  return shardFor(userId).query('SELECT * FROM users WHERE id = ?', userId);
}

function findByEmail(email) {
  // look the user up by email
  return Promise.all(shards.map(s =>
    s.query('SELECT * FROM users WHERE email = ?', email)
  )).then(rs => rs.flat()[0]);
}
